-- !! ISOLATED DATABASE ONLY (Supabase branch / local Postgres). NEVER production. !!
--
-- Safety interlocks (the script aborts, changing nothing, if any fails):
--   1. you must have run   set nlh.allow_synthetic_seed = 'on';   in the same session;
--   2. public.students must contain no row whose notes do not start 'SYNTHETIC';
--   3. public.franchisees must contain no row whose business_name does not start 'SYN '.
-- The live project holds real students, so interlock 2 stops it there.
-- ============================================================================
begin;

do $guard$
begin
  if coalesce(current_setting('nlh.allow_synthetic_seed', true), '') <> 'on' then
    raise exception 'Synthetic seed refused: run  set nlh.allow_synthetic_seed = ''on'';  first (isolated databases only).';
  end if;
  if exists (select 1 from public.students where coalesce(notes, '') not like 'SYNTHETIC%') then
    raise exception 'Synthetic seed refused: non-synthetic students exist - this looks like a real database.';
  end if;
  if exists (select 1 from public.franchisees where business_name not like 'SYN %') then
    raise exception 'Synthetic seed refused: non-synthetic franchisees exist - this looks like a real database.';
  end if;
end $guard$;

